import { useCallback, useEffect, useRef, useState } from "react";
import { supabase } from "../lib/supabase";

const ADMIN_EMAILS = ["meliodasrei653@gmail.com", "gojosatorumetade123@gmail.com"];
const fmt = v => Number(v || 0).toLocaleString("pt-BR");
const isAdmin = user => ADMIN_EMAILS.includes((user?.email || "").toLowerCase());
const errorText = e => e?.message || "Ocorreu um erro inesperado.";

async function rows(table, order = "created_at") {
  const { data, error } = await supabase.from(table).select("*").order(order, { ascending: false });
  if (error) throw error;
  return data || [];
}
function Shell({ kicker, title, description, children }) {
  return <div className="arp-page"><div className="arp-head"><span>{kicker}</span><h1>{title}</h1><p>{description}</p></div>{children}</div>;
}
function Empty({ icon = "✦", title, description }) {
  return <div className="arp-empty"><div>{icon}</div><h2>{title}</h2><p>{description}</p></div>;
}
function NoticeError({ children }) { return children ? <p className="arp-error" role="alert">{children}</p> : null; }
function Cards({ data }) {
  return <div className="arp-list">{data.map(x => <article className="arp-card" key={x.id}>{(x.image_url || x.banner_url) && <img src={x.image_url || x.banner_url} alt="" />}<div><b>{x.category || x.status || "ASTRARPG"}</b><h2>{x.title || x.name}</h2><p>{x.content || x.description || ""}</p></div></article>)}</div>;
}

export function NewsPage() {
  const [data,setData]=useState(null),[error,setError]=useState("");
  useEffect(()=>{let live=true;rows("news").then(v=>live&&setData(v.filter(x=>x.is_active!==false))).catch(e=>live&&setError(errorText(e)));return()=>{live=false}},[]);
  return <Shell kicker="ASTRARPG" title="Novidades" description="Acompanhe tudo que está acontecendo no universo.">{error?<NoticeError>{error}</NoticeError>:data===null?<div className="arp-loading">Carregando...</div>:data.length?<Cards data={data}/>:<Empty title="Nenhuma novidade publicada" description="As novidades publicadas pela administração aparecerão aqui."/>}</Shell>;
}
